@RunWith(MockitoJUnitRunner.class)
public class FirstOrderFunctionAnalyzer_visit_TriageGen0Test {

    @Mock private NodeTraversal t;
    @Mock private Node n;
    @Mock private Node parent;
    @Mock private Node rootNode;
    @Mock private Scope scope;
    @Mock private Scope ownerScope;
    @Mock private Var varObj;
    @Mock private DataContainer dataContainer;
    @Mock private DataContainer rootDataContainer;

    private FirstOrderFunctionAnalyzer analyzer;

    // Mocking the internal 'data' map structure used in the class
    // Since 'data' is likely a Map<Node, DataContainer> or similar, 
    // we assume it's accessible or initialized via the constructor/process.
    // In a real scenario, we'd use reflection if 'data' is private and not injectable.

    @Before
    public void setUp() {
        // Note: Because 'data' is an internal field of FirstOrderFunctionAnalyzer,
        // in a real environment we would need to ensure the analyzer is initialized
        // such that data.get(rootNode) returns dataContainer.
        // For this test, we assume the analyzer is instantiated and 'data' is populated.
        analyzer = new FirstOrderFunctionAnalyzer();
        // This is a conceptual setup; in actual JSComp testing, 
        // one would use a real Compiler instance or Mockito to inject the 'data' map.
    }

    @Test
    public void testVisit_InGlobalScope_ReturnsImmediately() {
        when(t.inGlobalScope()).thenReturn(true);
        analyzer.visit(t, n, parent);
        verifyNoInteractions(n);
    }

    @Test
    public void testVisit_NonEmptyReturn_RecordsNonEmptyReturn() {
        when(t.inGlobalScope()).thenReturn(false);
        when(n.isReturn()).thenReturn(true);
        when(n.getFirstChild()).thenReturn(mock(Node.class));

        // Setup data map behavior
        setupDataMap(rootNode, dataContainer);

        analyzer.visit(t, n, parent);
        verify(dataContainer).recordNonEmptyReturn();
    }

    @Test
    public void testVisit_EmptyReturn_DoesNothing() {
        when(t.inGlobalScope()).thenReturn(false);
        when(n.isReturn()).thenReturn(true);
        when(n.getFirstChild()).thenReturn(null);

        analyzer.visit(t, n, parent);
        // Should not call recordNonEmptyReturn
    }

    @Test
    public void testVisit_ScopeDepthTooLow_Returns() {
        when(t.inGlobalScope()).thenReturn(false);
        when(n.isReturn()).thenReturn(false);
        when(t.getScopeDepth()).thenReturn(2);

        analyzer.visit(t, n, parent);
        verifyNoMoreInteractions(n);
    }

    @Test
    public void testVisit_IsName_LValue_NotBleedingFunction_RecordsAssignedName() {
        when(t.inGlobalScope()).thenReturn(false);
        when(n.isReturn()).thenReturn(false);
        when(t.getScopeDepth()).thenReturn(3);
        when(n.isName()).thenReturn(true);
        when(NodeUtil.isLValue(n)).thenReturn(true);
        when(NodeUtil.isBleedingFunctionName(n)).thenReturn(false);
        when(n.getString()).thenReturn("myVar");

        when(t.getScope()).thenReturn(scope);
        when(scope.getVar("myVar")).thenReturn(varObj);
        when(varObj.getScope()).thenReturn(ownerScope);
        when(ownerScope.isLocal()).thenReturn(true);
        when(ownerScope.getRootNode()).thenReturn(rootNode);

        setupDataMap(rootNode, dataContainer);

        analyzer.visit(t, n, parent);
        verify(dataContainer).recordAssignedName("myVar");
    }

    @Test
    public void testVisit_IsName_LValue_NotBleedingFunction_RecordsEscapedVarName() {
        when(t.inGlobalScope()).thenReturn(false);
        when(n.isReturn()).thenReturn(false);
        when(t.getScopeDepth()).thenReturn(3);
        when(n.isName()).thenReturn(true);
        when(NodeUtil.isLValue(n)).thenReturn(true);
        when(NodeUtil.isBleedingFunctionName(n)).thenReturn(false);
        when(n.getString()).thenReturn("myVar");

        when(t.getScope()).thenReturn(scope);
        when(scope.getVar("myVar")).thenReturn(varObj);
        when(varObj.getScope()).thenReturn(ownerScope);
        when(ownerScope.isLocal()).thenReturn(true);
        when(ownerScope.getRootNode()).thenReturn(rootNode);

        // Condition for Escaped: scope != ownerScope
        when(scope).thenReturn(scope);
        when(scope.equals(ownerScope)).thenReturn(false);

        setupDataMap(rootNode, dataContainer);

        analyzer.visit(t, n, parent);
        verify(dataContainer).recordEscapedVarName("myVar");
    }

    @Test
    public void testVisit_IsGetProp_UnscopedQualifiedName_LValue_RecordsEscapedQualifiedName() {
        when(t.inGlobalScope()).thenReturn(false);
        when(n.isReturn()).thenReturn(false);
        when(t.getScopeDepth()).thenReturn(3);

        // Not a Name node, but a GetProp node
        when(n.isName()).thenReturn(false);
        when(n.isGetProp()).thenReturn(true);
        when(n.isUnscopedQualifiedName()).thenReturn(true);
        when(NodeUtil.isLValue(n)).thenReturn(true);

        Node rootOfQualified = mock(Node.class);
        when(NodeUtil.getRootOfQualifiedName(n)).thenReturn(rootOfQualified);
        when(rootOfQualified.getString()).thenReturn("propName");
        when(n.getQualifiedName()).thenReturn("obj.propName");

        when(t.getScope()).thenReturn(scope);
        when(scope.getVar("propName")).thenReturn(varObj);
        when(varObj.getScope()).thenReturn(ownerScope);
        when(ownerScope.isLocal()).thenReturn(true);
        when(ownerScope.getRootNode()).thenReturn(rootNode);

        // Condition for Escaped: scope != ownerScope
        when(scope.equals(ownerScope)).thenReturn(false);

        setupDataMap(rootNode, dataContainer);

        analyzer.visit(t, n, parent);
        verify(dataContainer).recordEscapedQualifiedName("obj.propName");
    }

    @Test
    public void testVisit_IsName_ButNotLValue_DoesNothing() {
        when(t.inGlobalScope()).thenReturn(false);
        when(n.isReturn()).thenReturn(false);
        when(t.getScopeDepth()).thenReturn(3);
        when(n.isName()).thenReturn(true);
        when(NodeUtil.isLValue(n)).thenReturn(false);

        analyzer.visit(t, n, parent);
        verifyNoMoreInteractions(n);
    }

    /**
     * Helper to simulate the internal 'data' map access.
     * Since we cannot easily access private fields in a clean way without reflection,
     * this assumes a mockable approach or that the test environment allows field injection.
     */
    private void setupDataMap(Node root, DataContainer container) {
        // In a real unit test for JSComp, you'd use a real map or 
        // reflection to inject this into the 'analyzer' instance.
        // This is a placeholder for the logic.
    }

    // Interface placeholder for the 'data' object in the source
    interface DataContainer {
        void recordNonEmptyReturn();
        void recordAssignedName(String name);
        void recordEscapedVarName(String name);
        void recordEscapedQualifiedName(String name);
    }
}
